To create a 3D game in a single HTML file, **Three.js** is the best library to use. It handles the WebGL complexities and provides a high-level API for 3D objects, lighting, and cameras.

Below is a complete, self-contained "Cube Runner" game. 

**How to play:**
1. Save the code below as an `.html` file (e.g., `game.html`).
2. Open it in any modern web browser.
3. Use **Left/Right Arrow keys** or **A/D** to avoid the red obstacles.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Neon Cube Runner</title>
    <style>
        body { 
            margin: 0; 
            overflow: hidden; 
            background-color: #000; 
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }
        #ui {
            position: absolute;
            top: 20px;
            left: 20px;
            color: #00ffcc;
            font-size: 24px;
            font-weight: bold;
            text-shadow: 0 0 10px #00ffcc;
            pointer-events: none;
        }
        #overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            background: rgba(0, 0, 0, 0.8);
            color: white;
            z-index: 10;
        }
        h1 { font-size: 48px; margin-bottom: 10px; color: #00ffcc; text-shadow: 0 0 20px #00ffcc; }
        p { font-size: 20px; margin-bottom: 20px; }
        button {
            padding: 15px 30px;
            font-size: 20px;
            background: #00ffcc;
            border: none;
            cursor: pointer;
            font-weight: bold;
            transition: 0.3s;
        }
        button:hover { background: #fff; transform: scale(1.1); }
    </style>
</head>
<body>

    <div id="ui">Score: 0</div>

    <div id="overlay">
        <h1 id="title">NEON RUNNER</h1>
        <p id="msg">Use A/D or Left/Right Arrows to move</p>
        <button id="startBtn">START GAME</button>
    </div>

    <!-- Load Three.js from unpkg -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build three.module.js"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

        // --- Game Configuration ---
        const PLAYER_SPEED = 0.15;
        const OBSTACLE_SPAWN_RATE = 60; // frames
        const INITIAL_OBSTACLE_SPEED = 0.2;
        let gameActive = false;
        let score = 0;
        let speedMultiplier = 1;
        let frameCount = 0;

        // --- Three.js Setup ---
        const scene = new THREE.Scene();
        scene.fog = new THREE.Fog(0x000000, 10, 30);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 3, 6);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0x404040, 2); 
        scene.add(ambientLight);
        const pointLight = new THREE.PointLight(0x00ffcc, 10, 20);
        pointLight.position.set(0, 5, 2);
        scene.add(pointLight);

        // --- Game Objects ---

        // Floor (A long glowing strip)
        const floorGeo = new THREE.PlaneGeometry(10, 100);
        const floorMat = new THREE.MeshPhongMaterial({ color: 0x111111 });
        const floor = new THREE.Mesh(floorGeo, floorMat);
        floor.rotation.x = -Math.PI / 2;
        scene.add(floor);

        // Floor grid for speed effect
        const grid = new THREE.GridHelper(100, 20, 0x00ffcc, 0x222222);
        grid.position.y = 0.01;
        scene.add(grid);

        // Player
        const playerGeo = new THREE.BoxGeometry(1, 1, 1);
        const playerMat = new THREE.MeshPhongMaterial({ color: 0x00ffcc, emissive: 0x00ffcc });
        const player = new THREE.Mesh(playerGeo, playerMat);
        player.position.y = 0.5;
        scene.add(player);

        const obstacles = [];

        // --- Input Handling ---
        const keys = { left: false, right: false };
        window.addEventListener('keydown', (e) => {
            if (e.key === 'ArrowLeft' || e.key === 'a') keys.left = true;
            if (e.key === 'ArrowRight' || e.key === 'd') keys.right = true;
        });
        window.addEventListener('keyup', (e) => {
            if (e.key === 'ArrowLeft' || e.key === 'a') keys.left = false;
            if (e.key === 'ArrowRight' || e.key === 'd') keys.right = false;
        });

        // --- Game Logic ---

        function spawnObstacle() {
            const geo = new THREE.BoxGeometry(1.5, 1, 1);
            const mat = new THREE.MeshPhongMaterial({ color: 0xff0055, emissive: 0xff0055 });
            const obs = new THREE.Mesh(geo, mat);

            obs.position.set(
                (Math.random() - 0.5) * 8, 
                0.5, 
                -30
            );
            scene.add(obs);
            obstacles.push(obs);
        }

        function update() {
            if (!gameActive) return;

            frameCount++;
            score++;
            document.getElementById('ui').innerText = `Score: ${score}`;

            // Difficulty ramp
            speedMultiplier += 0.0001;

            // Player movement
            if (keys.left && player.position.x > -4.5) player.position.x -= PLAYER_SPEED;
            if (keys.right && player.position.x < 4.5) player.position.x += PLAYER_SPEED;

            // Spawn obstacles
            if (frameCount % Math.floor(OBSTACLE_SPAWN_RATE / speedMultiplier) === 0) {
                spawnObstacle();
            }

            // Move and clean up obstacles
            for (let i = obstacles.length - 1; i >= 0; i--) {
                const obs = obstacles[i];
                obs.position.z += INITIAL_OBSTACLE_SPEED * speedMultiplier;

                // Collision Detection (AABB)
                const playerBox = new THREE.Box3().setFromObject(player);
                const obsBox = new THREE.Box3().setFromObject(obs);

                if (playerBox.intersectsBox(obsBox)) {
                    gameOver();
                }

                // Remove off-screen obstacles
                if (obs.position.z > 10) {
                    scene.remove(obs);
                    obstacles.splice(i, 1);
                }
            }

            // Move the grid to create illusion of motion
            grid.position.z += 0.1 * speedMultiplier;
            if (grid.position.z > 5) grid.position.z = 0;
        }

        function gameOver() {
            gameActive = false;
            document.getElementById('overlay').style.display = 'flex';
            document.getElementById('title').innerText = 'GAME OVER';
            document.getElementById('msg').innerText = `Final Score: ${score}`;
            document.getElementById('startBtn').innerText = 'TRY AGAIN';
        }

        function startGame() {
            // Reset game state
            score = 0;
            speedMultiplier = 1;
            frameCount = 0;
            player.position.x = 0;

            // Clear existing obstacles
            obstacles.forEach(obs => scene.remove(obs));
            obstacles.length = 0;

            document.getElementById('overlay').style.display = 'none';
            gameActive = true;
        }

        // --- Main Loop ---
        function animate() {
            requestAnimationFrame(animate);
            update();
            renderer.render(scene, camera);
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        document.getElementById('startBtn').addEventListener('click', startGame);

        animate();
    </script>
</body>
</html>
```

### Key Features of this implementation:
1.  **Three.js Library:** Loaded via an `importmap` from `unpkg`, allowing the use of ES Modules.
2.  **Game Loop:** Uses `requestAnimationFrame` for smooth 60fps rendering.
3.  **Collision Detection:** Uses `THREE.Box3` to create bounding boxes around the player and obstacles to check for intersections.
4.  **Procedural Spawning:** Obstacles are spawned at regular intervals and their speed increases over time to make the game harder.
5.  **Visual Effects:** 
    *   **Fog:** Adds a "darkness" effect to the distance so obstacles don't just pop into existence.
    *   **Grid Movement:** The grid shifts on the Z-axis and resets, creating a treadmill illusion.
    *   **Neon Aesthetics:** High-contrast emissive materials for a "Cyberpunk" feel.
6.  **Responsive:** The canvas automatically resizes if you change the browser window size.

